class Solution:
    def permuteUnique(self, nums: List[int]) -> List[List[int]]:
        res = []
        nums.sort()
        def backtrack(path, counter):
            if len(path) == len(nums):
                res.append(list(path))
                return
            for x in counter:
                if counter[x] > 0:
                    path.append(x)
                    counter[x] -= 1
                    backtrack(path, counter)
                    counter[x] += 1
                    path.pop()
        backtrack([], collections.Counter(nums))
        return res

