using namespace std;

void backtrack(vector<int>& path, map<int, int>& counter, int n, vector<vector<int>>& res) {
    if (path.size() == n) {
        res.push_back(path);
        return;
    }
    for (auto& pair : counter) {
        if (pair.second > 0) {
            path.push_back(pair.first);
            pair.second--;
            backtrack(path, counter, n, res);
            pair.second++;
            path.pop_back();
        }
    }
}

vector<vector<int>> permuteUnique(vector<int>& nums) {
    vector<vector<int>> res;
    map<int, int> counter;
    for (int n : nums) counter[n]++;
    vector<int> path;
    backtrack(path, counter, nums.size(), res);
    return res;
}

