import java.util.*;
import java.io.*;

public class Main {
    public static List<List<Integer>> permuteUnique(int[] nums) {
        List<List<Integer>> res = new ArrayList<>();
        Map<Integer, Integer> counter = new HashMap<>();
        for (int n : nums) counter.put(n, counter.getOrDefault(n, 0) + 1);
        backtrack(new ArrayList<>(), counter, nums.length, res);
        return res;
    }

    private static void backtrack(List<Integer> path, Map<Integer, Integer> counter, int n, List<List<Integer>> res) {
        if (path.size() == n) {
            res.add(new ArrayList<>(path));
            return;
        }
        for (int key : counter.keySet()) {
            int count = counter.get(key);
            if (count > 0) {
                path.add(key);
                counter.put(key, count - 1);
                backtrack(path, counter, n, res);
                counter.put(key, count);
                path.remove(path.size() - 1);
            }
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine(); if (line == null) return;
        line = line.replace("[", "").replace("]", "").replace(",", " ").trim();
        if (line.isEmpty()) { System.out.println("[]"); return; }
        String[] parts = line.split("\\s+");
        int[] nums = new int[parts.length];
        for (int i = 0; i < parts.length; i++) nums[i] = Integer.parseInt(parts[i]);
        System.out.println(permuteUnique(nums));
    }
}

