const fs = require('fs');

function permuteUnique(nums) {
    let res = [];
    nums.sort((a, b) => a - b);
    let counter = new Map();
    for (let n of nums) counter.set(n, (counter.get(n) || 0) + 1);
    function backtrack(path) {
        if (path.length === nums.length) {
            res.push([...path]);
            return;
        }
        for (let [key, count] of counter.entries()) {
            if (count > 0) {
                path.push(key);
                counter.set(key, count - 1);
                backtrack(path);
                counter.set(key, count);
                path.pop();
            }
        }
    }
    backtrack([]);
    return res;
}

